{
  "done": false,
  "tool": "manage_backends",
  "args": {
    "name": "Vol Desk Data",
    "operation": "add",
    "widgets_json": {
      "vol_symbol_pack": {
        "name": "Vol Symbol Pack",
        "description": "Volatility review filtered by symbol.",
        "endpoint": "/vol-symbol-pack",
        "type": "table",
        "params": [
          {
            "paramName": "symbol",
            "type": "ticker",
            "label": "Symbol",
            "value": "MSFT"
          },
          {
            "paramName": "only_liquid",
            "type": "boolean",
            "label": "Liquid only",
            "value": true
          }
        ],
        "data": {
          "staleTime": 900000
        },
        "gridData": {
          "w": 20,
          "h": 9
        }
      },
      "vol_regime_metric": {
        "name": "Vol Regime",
        "description": "Current volatility regime score.",
        "endpoint": "/vol-regime",
        "type": "metric",
        "data": {
          "staleTime": 900000
        },
        "gridData": {
          "w": 6,
          "h": 4
        }
      },
      "vix_history": {
        "name": "VIX History",
        "description": "Daily CBOE VIX closes with returns.",
        "endpoint": "/vix-history",
        "type": "table",
        "params": [
          {
            "paramName": "window",
            "type": "number",
            "label": "Window",
            "value": 30,
            "min": 5,
            "max": 365
          }
        ],
        "data": {
          "staleTime": 900000,
          "columnsDefs": [
            {
              "field": "date",
              "headerName": "Date",
              "cellDataType": "dateString"
            },
            {
              "field": "close",
              "headerName": "Close",
              "cellDataType": "number"
            },
            {
              "field": "return_pct",
              "headerName": "Return %",
              "cellDataType": "number",
              "formatterFn": "percent",
              "renderFn": "greenRed"
            }
          ]
        },
        "gridData": {
          "w": 20,
          "h": 9
        }
      }
    }
  }
}

